from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    order = names if name_order == "ascending" else names[::-1]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    choices = []
    for name in names:
        rows = sorted(packages[name], key=lambda row: row["version"])
        allowed = [row for row in rows
                   if row["version"] not in blocked.get(name, [])
                   and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + allowed)

    best_key = None
    best_versions = None
    for selection in product(*choices):
        selected = {name: row for name, row in zip(names, selection)
                    if row is not None}
        versions = {name: row["version"] for name, row in selected.items()}
        if any(name not in versions or not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in selected}
        valid = True
        for name, row in selected.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in versions or
                        not dep["min"] <= versions[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Only packages reachable from roots belong to the installation.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        # Reject cycles, including self-loops.
        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for child in edges.get(name, []):
                if not visit(child):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in selected):
            continue

        vector = tuple(versions.get(name, -1) for name in order)
        if best_key is None or (vector > best_key if preference == "maximum"
                                else vector < best_key):
            best_key = vector
            best_versions = versions
    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def solve_01(data):
    return dependency_solver(data, "maximum", "descending")


def solve_02(data):
    return dependency_solver(data, "minimum", "descending")


def solve_03(data):
    return dependency_solver(data, "maximum", "ascending")


def solve_04(data):
    return dependency_solver(data, "minimum", "ascending")


def solve_05(data):
    return dependency_solver(data, "maximum", "descending")


def rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def solve_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def solve_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for chosen in combinations(available, k):
        ids = {job["id"] for job in chosen}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        ends = []
        feasible = True
        for job in sorted(chosen, key=lambda item: (item["start"], item["end"], item["id"])):
            ends = [end for end in ends if end > job["start"]]
            ends.append(job["end"])
            if len(ends) > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in chosen)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def solve_08(data):
    required = data.get("required", [])
    index = {node: bit for bit, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = 1 << index[data["source"]] if data["source"] in index else 0
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, coupons - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | (1 << index[next_node] if next_node in index else 0)
                next_state = (next_node, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": solve_01,
    "component_02": solve_02,
    "component_03": solve_03,
    "component_04": solve_04,
    "component_05": solve_05,
    "component_06": solve_06,
    "component_07": solve_07,
    "component_08": solve_08,
}
